from pathlib import Path
from html.parser import HTMLParser
from hashlib import sha256
import json, re

class VisibleText(HTMLParser):
    def __init__(self):
        super().__init__()
        self.hidden = []
        self.parts = []
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style', 'template'):
            self.hidden.append(tag)
        elif tag in ('p', 'li', 'h1', 'h2', 'h3', 'br') and not self.hidden:
            self.parts.append('\n')
    def handle_endtag(self, tag):
        if self.hidden and tag == self.hidden[-1]:
            self.hidden.pop()
        elif tag in ('p', 'li', 'h1', 'h2', 'h3') and not self.hidden:
            self.parts.append('\n')
    def handle_data(self, data):
        if not self.hidden:
            self.parts.append(data)

base = Path('products/services/sqlite-repair/international-cad')
raw = (base / 'raw/interac-etransfer.html').read_bytes()
digest = sha256(raw).hexdigest()
assert digest == '4251ea3c323f733222dec9eb4d966c3507778b0f848c3bb655788ef3cfe91d56'
parser = VisibleText()
parser.feed(raw.decode('utf-8'))
lines = [' '.join(line.split()) for line in ''.join(parser.parts).splitlines()]
pattern = re.compile(r'participating|Canadian (?:bank|financial institution|account)|international|(?:sender|recipient|requestor).{0,100}(?:account|institution)', re.I)
passages = list(dict.fromkeys(line for line in lines if pattern.search(line) and 0 < len(line) <= 1000))
result = {'receipt': 'TASK-179560440301', 'source': 'https://www.interac.ca/en/payments/business/interac-e-transfer-business-request-money/', 'capture_sha256': digest, 'candidate_source_passages': passages[:20], 'operator_scoping_question_en': 'If you decide to proceed, can you pay in CAD using Interac e-Transfer through a participating financial institution?', 'operator_scoping_question_fr': 'Si vous décidez de poursuivre, pouvez-vous payer en dollars canadiens par Virement Interac auprès d’une institution financière participante?', 'scope': 'Published source excerpts for manual verification. Buyer compatibility, operator acceptance and Treasury settlement are unverified.'}
output = base / 'director-interac-source-crosswalk.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
